var stdoutSink = (e10) => process.stdout.write(JSON.stringify(e10) + "\n");
function createLogger(opts = {}) {
  const sink = opts.sink ?? stdoutSink;
  const bound = opts.bound ?? {};
  const emit = (level, msg, fields) => {
    sink({ ts: (/* @__PURE__ */ new Date()).toISOString(), level, msg, ...bound, ...fields });
  };
  return {
    info: (m4, f2) => emit("info", m4, f2),
    warn: (m4, f2) => emit("warn", m4, f2),
    error: (m4, f2) => emit("error", m4, f2),
    child: (more) => createLogger({ sink, bound: { ...bound, ...more } })
  };
}
var noopLogger = createLogger({ sink: () => {
} });

