        { order: 2, action: "\u57FA\u4E8E\u76F8\u5173 Rich \u8BB0\u5F55\u5B9E\u65BD\u6700\u5C0F\u53D8\u66F4", verification: "\u6BCF\u9879\u53D8\u66F4\u90FD\u80FD\u8FFD\u6EAF\u5230\u76EE\u6807\u6216\u7EA6\u675F" },
        { order: 3, action: "\u6267\u884C\u9A8C\u8BC1\u5E76\u56DE\u5199\u7ED3\u679C", verification: "\u4EA7\u7269\u3001\u6D4B\u8BD5\u7ED3\u679C\u548C\u672A\u89E3\u51B3\u95EE\u9898\u90FD\u6709\u5F15\u7528" }
