var CURRENT_KEY2 = "center.current";
var PostgresStateRepo = class {
  constructor(pool) {
    this.pool = pool;
  }
  async getCenter() {
    const { rows } = await this.pool.query(
      "SELECT value, updated_at FROM state WHERE key = $1",
      [CURRENT_KEY2]
    );
    if (!rows[0]) return { elementId: null, updatedAt: null };
    return { elementId: rows[0].value || null, updatedAt: rows[0].updated_at };
  }
  async setCenter(elementId) {
    const client = await this.pool.connect();
    try {
      await client.query("BEGIN");
      const priorRows = await client.query(
        "SELECT value, updated_at FROM state WHERE key = $1",
        [CURRENT_KEY2]
      );
      const prior = priorRows.rows[0] ? { elementId: priorRows.rows[0].value || null, updatedAt: priorRows.rows[0].updated_at } : { elementId: null, updatedAt: null };
      const ts2 = (/* @__PURE__ */ new Date()).toISOString();
      const dwellMs = prior.updatedAt ? new Date(ts2).getTime() - new Date(prior.updatedAt).getTime() : null;
      await client.query(`
        INSERT INTO state (key, value, updated_at) VALUES ($1, $2, $3)
        ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value, updated_at=EXCLUDED.updated_at
      `, [CURRENT_KEY2, elementId, ts2]);
      await client.query(
        "INSERT INTO center_history (ts, from_id, to_id, dwell_ms) VALUES ($1, $2, $3, $4)",
        [ts2, prior.elementId, elementId, dwellMs]
      );
      await client.query("COMMIT");
      return { ts: ts2, from: prior.elementId, to: elementId, dwellMs };
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  }
  async recentChanges(limit = 20) {
    const { rows } = await this.pool.query(
      "SELECT ts, from_id, to_id, dwell_ms FROM center_history ORDER BY id DESC LIMIT $1",
      [limit]
    );
    return rows.map((r) => ({ ts: r.ts, from: r.from_id, to: r.to_id, dwellMs: r.dwell_ms }));
  }
};

